package ca.humber.stockbridge.service;
import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.web.client.*;import java.util.*;
@Service public class AlertClient {private final RestTemplate rest=new RestTemplate();@Value("${alerts.url:http://localhost:8081}")String url;@Value("${alerts.user:bridge}")String user;@Value("${alerts.password:bridge-dev-password}")String password;public record AlertResult(boolean online,Object data){}public AlertResult fetch(){try{HttpHeaders headers=new HttpHeaders();headers.setBasicAuth(user,password);ResponseEntity<Object[]> response=rest.exchange(url+"/api/alerts",HttpMethod.GET,new HttpEntity<>(headers),Object[].class);return new AlertResult(true,response.getBody());}catch(RestClientException ex){return new AlertResult(false,List.of());}}public boolean create(String message,String severity){try{HttpHeaders h=new HttpHeaders();h.setBasicAuth(user,password);h.setContentType(MediaType.APPLICATION_JSON);rest.exchange(url+"/api/alerts",HttpMethod.POST,new HttpEntity<>(Map.of("message",message,"severity",severity,"status","OPEN"),h),Object.class);return true;}catch(RestClientException ex){return false;}}}